package org.usbworkbench;
import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.*;
/** Original standard USBExtreme writer. Files only; never installs a console loader. */
public final class UsbExtreme {
 public static final long PART=1073741824L,MAX=16L*PART;
 public static final class Game {public final String title,id;public final int parts,media;Game(String t,String i,int n,int m){title=t;id=i;parts=n;media=m;}public String part(int i){return String.format(Locale.ROOT,"ul.%08X.%s.%02d",checksum(title),id,i);}public byte[] record(){byte[] b=new byte[64];byte[] t=title.getBytes(StandardCharsets.US_ASCII),name=("ul."+id).getBytes(StandardCharsets.US_ASCII);System.arraycopy(t,0,b,0,t.length);System.arraycopy(name,0,b,32,name.length);b[47]=(byte)parts;b[48]=(byte)media;b[53]=8;return b;}}
 public static Game game(String title,String id,int parts,int media)throws IOException{if(title==null||title.length()<1||title.length()>32||!title.equals(title.trim())||parts<1||parts>16||(media!=0x12&&media!=0x14)||id==null||!id.matches("[A-Z]{4}_[0-9]{3}\\.[0-9]{2}"))throw new IOException("UL_OPTIONS");for(int i=0;i<title.length();i++)if(title.charAt(i)<32||title.charAt(i)>126)throw new IOException("UL_OPTIONS");return new Game(title,id,parts,media);}
 /** Non-reflected polynomial CRC, initial0, includes terminating NUL (OPL title naming). */
 public static int checksum(String title){int crc=0;byte[] bytes=title.getBytes(StandardCharsets.US_ASCII);for(int i=0;i<=bytes.length;i++){crc^=(i==bytes.length?0:bytes[i]&255)<<24;for(int bit=0;bit<8;bit++)crc=(crc<<1)^((crc<0)?0x04c11db7:0);}return crc;}
 public static List<Game> read(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(n==0||out.size()>64000-n)throw new IOException("UL_CFG");out.write(buffer,0,n);}byte[] all=out.toByteArray();if(all.length==0||all.length%64!=0)throw new IOException("UL_CFG");List<Game> games=new ArrayList<>();Set<String> titles=new HashSet<>(),ids=new HashSet<>();for(int at=0;at<all.length;at+=64){String title=text(all,at,32),image=text(all,at+32,15);if(!image.startsWith("ul."))throw new IOException("UL_CFG");Game g;try{g=game(title,image.substring(3),all[at+47]&255,all[at+48]&255);}catch(IOException e){throw new IOException("UL_CFG");}if(!titles.add(title.toLowerCase(Locale.ROOT))||!ids.add(g.id))throw new IOException("UL_CFG");games.add(g);}return Collections.unmodifiableList(games);}
 private static String text(byte[] b,int at,int count)throws IOException{int end=at;while(end<at+count&&b[end]!=0){if(b[end]<32||b[end]>126)throw new IOException("UL_CFG");end++;}for(int i=end;i<at+count;i++)if(b[i]!=0)throw new IOException("UL_CFG");return new String(b,at,end-at,StandardCharsets.US_ASCII);}
 public static String discId(OpticalImage.Source source)throws IOException{OpticalImage.Manifest m=OpticalImage.scan(source,(a,b)->{});OpticalImage.Entry cfg=null;for(OpticalImage.Entry e:m.entries)if(!e.directory&&e.path.equalsIgnoreCase("SYSTEM.CNF"))cfg=e;if(cfg==null||cfg.size<1||cfg.size>65536)throw new IOException("UL_SYSTEM");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] contents=new byte[(int)cfg.size];OpticalImage.read(source,cfg,0,contents,0,contents.length);out.write(contents,0,contents.length);String text=new String(out.toByteArray(),StandardCharsets.US_ASCII);java.util.regex.Matcher matcher=java.util.regex.Pattern.compile("(?im)^\\s*BOOT2\\s*=\\s*cdrom0?:[\\\\/]([A-Za-z]{4}_[0-9]{3}\\.[0-9]{2});1\\s*$").matcher(text);if(!matcher.find())throw new IOException("UL_SYSTEM");String id=matcher.group(1).toUpperCase(Locale.ROOT);if(matcher.find())throw new IOException("UL_SYSTEM");return id;}
 private static byte[] fingerprint(OpticalImage.Source source,DiskTools.Progress p)throws IOException{MessageDigest digest=sha();byte[] b=new byte[65536];long size=source.size();for(long at=0;at<size;){p.update(at,size);int n=(int)Math.min(b.length,size-at);source.read(at,b,0,n);digest.update(b,0,n);at+=n;}return digest.digest();}
 private static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 private static MessageDigest sha(){try{return MessageDigest.getInstance("SHA-256");}catch(Exception e){throw new AssertionError(e);}}
 public static String write(OpticalImage.Source source,String title,String media,ConsoleParts.Sink sink,DiskTools.Progress progress)throws IOException{
  long size=source.size();if(size<2048||size>MAX||size%2048!=0)throw new IOException("UL_OPTIONS");Game game=game(title,discId(source),(int)((size+PART-1)/PART),media.equals("DVD")?0x14:media.equals("CD")?0x12:0);byte[] initial=fingerprint(source,progress),b=new byte[65536];MessageDigest hash=sha();long done=0;
  for(int i=0;i<game.parts;i++){String path=game.part(i);long count=Math.min(PART,size-done);MessageDigest part=sha();try(OutputStream out=sink.create(path)){for(long at=0;at<count;){progress.update(done*2+at,size*2);int n=(int)Math.min(b.length,count-at);source.read(done+at,b,0,n);out.write(b,0,n);hash.update(b,0,n);part.update(b,0,n);at+=n;}out.flush();}sink.sync(path);MessageDigest saved=sha();try(InputStream in=sink.reopen(path)){long read=0;while(read<count){progress.update(done*2+count+read,size*2);int n=in.read(b,0,(int)Math.min(b.length,count-read));if(n<=0)throw new IOException("VERIFY_FAILED");saved.update(b,0,n);read+=n;}if(in.read()!=-1)throw new IOException("VERIFY_FAILED");}if(!MessageDigest.isEqual(part.digest(),saved.digest()))throw new IOException("VERIFY_FAILED");done+=count;}
  byte[] record=game.record();try(OutputStream out=sink.create("ul.cfg")){out.write(record);out.flush();}sink.sync("ul.cfg");try(InputStream in=sink.reopen("ul.cfg")){List<Game> saved=read(in);if(saved.size()!=1||!Arrays.equals(saved.get(0).record(),record))throw new IOException("VERIFY_FAILED");}if(source.size()!=size)throw new IOException("SOURCE_CHANGED");byte[] digest=hash.digest();if(!MessageDigest.isEqual(initial,digest)||!MessageDigest.isEqual(initial,fingerprint(source,progress)))throw new IOException("SOURCE_CHANGED");progress.update(size*2,size*2);return game.id+"\n"+game.parts+"\n"+hex(digest);
 }
}
